 static JSONObject chat(String text,String reason)throws Exception{return new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("finish_reason",reason).put("message",new JSONObject().put("content",text).put("reasoning_content","hidden reasoning"))));}
