  List<SeekyAiCore.Message> messages=new ArrayList<>();for(int n=0;n<8;n++){messages.add(new SeekyAiCore.Message("user","question-"+n));messages.add(new SeekyAiCore.Message("assistant","answer-"+n));}List<SeekyAiCore.Message> history=SeekyAiCore.history(messages);ok(history.size()==6&&history.get(0).text.equals("question-5"),"only the last three complete exchanges enter the request");
