  SeekyAiClient.Network denied=new SeekyAiClient.Network(url->{last[0]=new Connection(url);last[0].code=429;return last[0];});try{denied.post(SeekyAiCore.GEMINI,KEY,request,new SeekyAiClient.Call());throw new AssertionError();}catch(IOException e){ok(e.getMessage().contains("quota")&&!e.getMessage().contains(KEY)&&last[0].disconnected,"quota error is explicit, sanitized and does not switch providers");}
  SeekyAiClient.Network redirect=new SeekyAiClient.Network(url->{Connection c=new Connection(url);c.code=302;return c;});rejects(()->redirect.post(SeekyAiCore.GEMINI,KEY,request,new SeekyAiClient.Call()),"provider redirect is not followed with a credential");
  SeekyAiClient.Network oversized=new SeekyAiClient.Network(url->{Connection c=new Connection(url);c.reply=new byte[262145];return c;});rejects(()->oversized.post(SeekyAiCore.GEMINI,KEY,request,new SeekyAiClient.Call()),"network response has a hard byte limit");
  SeekyAiClient.Call call=new SeekyAiClient.Call();SeekyAiClient.Network cancelled=new SeekyAiClient.Network(url->{last[0]=new Connection(url);last[0].cancelOnRead=call;return last[0];});rejects(()->cancelled.post(SeekyAiCore.GEMINI,KEY,request,call),"cancellation is observed while reading and stops the response");ok(last[0].disconnected&&call.connection==null,"cancelled connection is released");
