  String auth="AQ."+String.join("",Collections.nCopies(60,"a"));ok(SeekyAiClient.validKey(auth),"new dotted Google auth key format accepted without altering key");
  transport.verify(auth,new SeekyAiClient.Call());ok(last[0].getRequestMethod().equals("POST")&&last[0].getURL().getPath().endsWith(":generateContent")&&new JSONObject(last[0].body.toString("UTF-8")).getJSONObject("generationConfig").getInt("maxOutputTokens")==128&&!last[0].body.toString("UTF-8").contains("Trecho escolhido")&&last[0].getRequestProperty("x-goog-api-key").equals(auth)&&last[0].disconnected,"connection check actually generates bounded text with the production contract and no document");
  String err=new JSONObject().put("error",new JSONObject().put("message",KEY).put("details",new JSONArray().put(new JSONObject().put("reason","API_KEY_INVALID")))).toString();
  ok(SeekyAiClient.failure(400,err,KEY).contains("inválida")&&!SeekyAiClient.failure(400,err,KEY).contains(KEY),"invalid key reason is actionable without echoing server secrets");
  ok(SeekyAiClient.failure(403,err.replace("API_KEY_INVALID","API_KEY_ANDROID_APP_BLOCKED")).contains("restrita"),"application restriction failure distinguished from local storage");
  final int[] attempts={0};SeekyAiClient.Network badKey=new SeekyAiClient.Network(url->{attempts[0]++;Connection c=new Connection(url);c.code=400;c.reply=err.getBytes(StandardCharsets.UTF_8);return c;});rejects(()->badKey.verify(auth,new SeekyAiClient.Call()),"connection check rejects an invalid key without pretending it was verified");ok(attempts[0]==1,"connection test never retries or switches providers");
  String detail=new JSONObject().put("error",new JSONObject().put("status","INVALID_ARGUMENT").put("message","Invalid JSON payload: unknown field. token="+KEY)).toString();String diagnosis=SeekyAiClient.failure(400,detail,KEY);ok(diagnosis.contains("INVALID_ARGUMENT")&&diagnosis.contains("Invalid JSON payload")&&!diagnosis.contains(KEY),"HTTP 400 retains actionable Google detail while redacting exact credential");
  ok(!SeekyAiClient.redact("AQ."+String.join("",Collections.nCopies(60,"b"))+" AIza"+String.join("",Collections.nCopies(35,"c")),"").contains("bbbbbbbbbb"),"known Google auth key patterns are hidden even outside current credential");
  SeekyAiClient emptyTest=new SeekyAiClient((pr,k,b,c)->"{\"candidates\":[]}");rejects(()->emptyTest.verifyGeneration(KEY,new SeekyAiClient.Call()),"HTTP 200 with no generated text cannot pass connection verification");
  Path folder=Files.createTempDirectory("seeky-ai-store-");SeekyAiStore store=new SeekyAiStore(folder.toFile());SeekyAiStore.Session session=store.create("Livro","Apenas um trecho","Capítulo 2","content://test/book","text/plain","book.txt",1,3,4);session.put("pending","Pergunta por concluir");store.save(session);SeekyAiStore.Session resumed=store.load(session.id());ok(resumed.s("pending").equals("Pergunta por concluir")&&resumed.context().equals("Apenas um trecho"),"pending question and exact context survive reopening");resumed.append("Pergunta",new SeekyAiCore.Result("Resposta",false));store.save(resumed);ok(store.load(session.id()).messages.size()==2&&store.load(session.id()).s("pending").isEmpty(),"successful exchange is committed once without duplicate pending text");Files.write(folder.resolve(session.id()+".new"),"interrupted".getBytes(StandardCharsets.UTF_8));ok(store.load(session.id()).messages.size()==2,"uncommitted temporary write cannot replace valid history");rejects(()->store.load("../../outside"),"conversation path traversal is rejected");store.delete(session.id());ok(!store.file(session.id()).exists(),"deleting conversation removes only its own snapshot");
